<section class="p-section"><h2>Request a new batch</h2><p class="p-muted">TCM One activates batches and assigns official mentors after approval.</p><form class="p-form" method="post" action="<?= base_url('/partner/batches') ?>"><?= csrf_field() ?><label>Batch name<input name="batch_name" required></label><label>TCM One course<select name="course_id"><option value="">Select course</option><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['title']) ?></option><?php endforeach ?></select></label><label>Start date<input type="date" name="starts_on"></label><label>End date<input type="date" name="ends_on"></label><label>Class schedule<input name="schedule" placeholder="Days and time"></label><label>Delivery mode<select name="delivery_mode"><option>In person</option><option>Online</option><option>Hybrid</option></select></label><label>Capacity<input type="number" min="1" name="capacity"></label><label>Location<input name="location"></label><label>Proposed fee (₹)<input type="number" min="0" step="0.01" name="fee"></label><div class="wide"><button class="tcm-btn primary">Submit Batch Request</button></div></form></section>
<section class="p-section"><h2>Your batches</h2><?php if(!$rows): ?><div class="p-empty">No batches submitted.</div><?php else: ?><div class="p-table-wrap"><table class="p-table"><thead><tr><th>Batch</th><th>Course</th><th>Dates</th><th>Capacity</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['batch_name']) ?></td><td><?= e($r['course_title']??'—') ?></td><td><?= e($r['starts_on']??'—') ?> – <?= e($r['ends_on']??'—') ?></td><td><?= (int)$r['capacity'] ?></td><td><span class="p-pill"><?= e(str_replace('_',' ',$r['status'])) ?></span></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
